'use client';
/* eslint-disable react/prop-types -- Nested shared props are checked by the imported PhysisFeatureProps TypeScript contract. */
import { useEffect, useImperativeHandle, useRef, useState, type ReactNode, type Ref } from 'react';
import { useDialogAccessibility } from '../use-dialog-accessibility';
import { DialogCloseButton } from '../DialogCloseButton';
import { CalendarDatePicker } from '../CalendarDatePicker';
import { TimeClockPicker } from '../TimeClockPicker';
import { formatCalendarDateValue } from '../calendar-data';
import { addCivilDays, todayCivilDate } from '../calendar-context';
import { editPhysisRecord, newPhysisRecord, physisNumber, physisRecords, type PhysisFeatureProps, type PhysisRecord } from './types';
import {
  NUTRIENTS, NUTRIENT_KEYS, DEFAULT_FOOD_RULES, blankFood, nutrient, totalNutrients,
  snapshotItem, copyMeal, recipeFood, foodWarnings, energyDifference, estimateEnergy, startingNutritionTargets, resolveTargets,
  suggestPortion, importUsdaFood, summaryForDay, validateNutritionRecord,
  NUTRIENT_REFERENCES, compareNutrientReference,
  type Food, type FoodCategory, type NutrientKey, type Meal, type MealItem, type Recipe,
  type DietTemplate, type NutritionProfile, type NutritionTarget, type NutrientTotals,
} from './nutrition-domain';
import { oralNutrientsForDay, convertMass } from './care-domain';
import { createPhysisSubmission } from './submission';
import { nutritionPeriodRange } from './nutrition-periods';
import seed from './nutrition-seed.json';
import { FOOD_REFERENCES, FoodReferenceNote, SuperfoodCollectionNote, isTopFood, manualReferenceFoods } from './food-reference';
import { applyPersonalProfile, defaultNutritionProfile, type PersonalProfileDraft } from './personal-profile-domain';
import './nutrition.css';

export { validateNutritionRecord, summaryForDay } from './nutrition-domain';
type Props = PhysisFeatureProps;
type Translate = (ru: string, en: string) => string;
const core: NutrientKey[] = ['energy', 'protein', 'fat', 'carbohydrate', 'fiber'];
const categoryNames: Record<FoodCategory, [string, string]> = { soy: ['Соя и производные', 'Soy and derivatives'], legume: ['Бобовые', 'Legumes'], 'seed-oil': ['Масла из семян', 'Seed oils'] };
const fmt = (value: number | null | undefined) => value == null ? '—' : Number(value.toFixed(1)).toLocaleString('ru-RU');
const tr = (language: string): Translate => (ru, en) => language === 'ru' ? ru : en;
function profileFor(props: Props) { return physisRecords<NutritionProfile>(props.store, 'nutrition-profile')[0]; }
const foodGroups = ['ТОП СУПЕРФУДОВ', 'Фрукты', 'Овощи', 'Злаки', 'Орехи', 'Мясо и рыба', 'Яйца', 'Хлебобулочные', 'Молочные продукты', 'Бобовые', 'Масла и жиры', 'Напитки', 'Готовые блюда', 'Другое'];
type CatalogEntry = { id: string; food: Food; record: PhysisRecord<Food> | PhysisRecord<Recipe> };
function catalogFor(props: Props): CatalogEntry[] {
  const personal = props.store.records.flatMap<CatalogEntry>(record => record.kind === 'food' ? [{ id: record.id, food: record.data as Food, record: record as PhysisRecord<Food> }] : record.kind === 'recipe' ? [{ id: record.id, food: (record.data as Recipe).food, record: record as PhysisRecord<Recipe> }] : []);
  const descriptions: Record<number, { name: string; state: Food['state']; category: string; legume?: boolean }> = {
    ...Object.fromEntries(FOOD_REFERENCES.filter(entry => entry.fdcId).map(entry => [entry.fdcId!, { name: entry.name[0], state: entry.state, category: entry.category, legume: entry.legume }])),
    171688: { name: 'Яблоко с кожурой', state: 'raw', category: 'Фрукты' },
    171077: { name: 'Куриная грудка без кожи и костей', state: 'raw', category: 'Мясо и рыба' },
    169705: { name: 'Овёс', state: 'dry', category: 'Злаки' },
    172421: { name: 'Чечевица варёная, без соли', state: 'cooked', category: 'Бобовые', legume: true },
  };
  const base = seed.flatMap<CatalogEntry>(value => {
    const id = `00000000-0000-4000-8000-${String(value.fdcId).padStart(12, '0')}`;
    if (personal.some(entry => entry.id === id || entry.food.provenance.provider === 'USDA' && entry.food.provenance.id === String(value.fdcId))) return [];
    const food = importUsdaFood(value), description = descriptions[value.fdcId] ?? { name: food.name, state: 'unknown' as const, category: 'Другое' };
    const reference = FOOD_REFERENCES.find(entry => entry.fdcId === value.fdcId);
    food.aliases = [food.name, ...(reference?.name ?? []), ...(reference?.aliases ?? [])];
    food.name = props.language === 'ru' ? description.name : reference?.name[1] ?? food.name;
    food.state = description.state; food.category = description.category; food.compositionKnown = true; food.ingredients = food.name;
    if (reference?.top) food.collections = ['superfoods'];
    if (description.legume) { food.contains = ['legume']; food.legumePreparation = 'adequately-cooked'; }
    const record: PhysisRecord<Food> = { id, kind: 'food', schemaVersion: 1, createdAt: '2026-10-24T00:00:00Z', updatedAt: '2026-10-24T00:00:00Z', source: 'import', data: food };
    return [{ id, food, record }];
  });
  const manual = manualReferenceFoods(props.language).flatMap<CatalogEntry>(({id, food}) => {
    if (personal.some(entry => entry.id === id || entry.food.provenance.id === food.provenance.id)) return [];
    const record: PhysisRecord<Food> = { id, kind: 'food', schemaVersion: 1, createdAt: '2026-10-25T00:00:00Z', updatedAt: '2026-10-25T00:00:00Z', source: 'import', data: food };
    return [{ id, food, record }];
  });
  return [...personal, ...base, ...manual];
}
function useActions() {
  const [submitCreation] = useState(createPhysisSubmission);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function run(action: () => void | Promise<void>) {
    if (busy) return;
    setBusy(true); setError('');
    try { await action(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось сохранить / Could not save'); }
    finally { setBusy(false); }
  }
  return { busy, error, run, submitCreation };
}
function ErrorMessage({ error }: { error: string }) { return error ? <p className="physis-warning" role="alert">{error}</p> : null; }
function validateAndSave(props: Props, record: PhysisRecord) {
  if (!validateNutritionRecord(record)) throw new Error(tr(props.language)('Проверьте данные, единицы и обязательные поля.', 'Check values, units and required fields.'));
  return props.store.save(record);
}
function Warnings({ food, props }: { food: Food; props: Props }) {
  const t = tr(props.language);
  const warnings = foodWarnings(food, profileFor(props)?.data.foodRules ?? DEFAULT_FOOD_RULES, props.language);
  return <>{warnings.map((warning, index) => <details className="physis-nutrition-warning" key={`${warning.type}-${index}`}><summary>{warning.type === 'personal' ? t('Личное правило: ', 'Personal rule: ') : ''}{warning.text}</summary><p>{warning.scope}</p><p>{t('Основание', 'Source')}: {warning.source.startsWith('https://') ? <a href={warning.source} target="_blank" rel="noreferrer">{warning.source}</a> : warning.source} · {warning.reviewedAt}</p></details>)}</>;
}
function NutrientSummary({ totals, target, props, compact = false, full = false }: { totals: NutrientTotals; target?: NutritionTarget; props: Props; compact?: boolean; full?: boolean }) {
  const t = tr(props.language);
  const selected = profileFor(props)?.data.selectedNutrients ?? ['sodium', 'magnesium'];
  const keys = full ? NUTRIENT_KEYS : compact ? core.slice(0, 4) : [...new Set([...core, ...selected])] as NutrientKey[];
  return <div className="physis-table-wrap"><table className="physis-nutrition-table"><caption className="physis-sr-only">{t('Сводка питания', 'Nutrition summary')}</caption><thead><tr><th scope="col">{t('Показатель', 'Nutrient')}</th><th scope="col">{t('Учтено', 'Logged')}</th>{target && <th scope="col">{t('Цель / остаток', 'Target / remaining')}</th>}</tr></thead><tbody>{keys.map(key => {
    const total = totals[key];
    const goal = target && key in target ? target[key as keyof NutritionTarget] : null;
    const energyFactor = key === 'energy' && props.settings.energyUnit === 'kJ' ? 4.184 : 1;
    const unit = energyFactor === 1 ? NUTRIENTS[key].unit : 'kJ';
    return <tr key={key}><th scope="row">{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)}</th><td>{total.knownItems === 0 ? '—' : `${total.value === null ? '≥ ' : ''}${fmt(total.knownValue * energyFactor)} ${unit}`}{total.value === null && <small>{t('Данные есть', 'Known')}: {total.knownItems}/{total.totalItems}</small>}</td>{target && <td>{goal == null ? '—' : <>{fmt(goal * energyFactor)} / {total.value === null ? t('неизвестен', 'unknown') : fmt((goal - total.knownValue) * energyFactor)} {unit}</>}</td>}</tr>;
  })}</tbody></table></div>;
}

function NutrientSources({ props, date }: { props: Props; date: string }) {
  const t = tr(props.language), profile = profileFor(props)?.data;
  const summary = summaryForDay(props.store, date);
  const sources = oralNutrientsForDay(props.store, date);
  const keys = [...new Set([...(profile?.selectedNutrients ?? ['sodium', 'magnesium']), 'magnesium'])].filter(key => key !== 'energy') as NutrientKey[];
  function fromCare(key: NutrientKey, category: 'supplement' | 'medicine') {
    const seen = new Set<string>();
    return sources.filter(source => source.nutrient === key && source.category === category).reduce((sum, source) => {
      const identity = `${source.intakeId}:${source.nutrient}:${source.value}:${source.unit}`;
      if (seen.has(identity)) return sum;
      seen.add(identity);
      return sum + (convertMass(source.value, source.unit, NUTRIENTS[key].unit) ?? 0);
    }, 0);
  }
  return <details><summary>{t('Нутриенты: еда, БАДы и лекарства', 'Nutrients: food, supplements and medicines')}</summary><div className="physis-table-wrap"><table className="physis-nutrition-table"><caption>{t('Только фактические приёмы; одинаковые единицы приведены к единице показателя', 'Actual intake only; compatible units are converted')}</caption><thead><tr><th scope="col">{t('Показатель', 'Nutrient')}</th><th scope="col">{t('Еда', 'Food')}</th><th scope="col">{t('БАДы', 'Supplements')}</th><th scope="col">{t('Лекарства', 'Medicines')}</th><th scope="col">{t('Всего', 'Total')}</th></tr></thead><tbody>{keys.map(key => {
    const food = summary.actual[key], supplement = fromCare(key, 'supplement'), medicine = fromCare(key, 'medicine');
    return <tr key={key}><th scope="row">{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)} ({NUTRIENTS[key].unit})</th><td>{food.value === null ? '≥ ' : ''}{fmt(food.knownValue)}<small>{t('В том числе продукты с обогащением', 'Including fortified foods')}: {fmt(summary.fortified[key].knownValue)}</small></td><td>{fmt(supplement)}</td><td>{fmt(medicine)}</td><td>{food.value === null ? '≥ ' : ''}{fmt(food.knownValue + supplement + medicine)}</td></tr>;
  })}</tbody></table></div><p className="physis-muted">{t('Из препаратов учитывается только указанное элементарное содержание фактически принятых пероральных единиц. Дозы в мл, мг, каплях, инъекции и неописанные нутриенты не пересчитываются автоматически. Отметка «обогащённый» относится к продукту целиком; она не выделяет добавленную долю нутриента.', 'Medicines contribute only declared elemental content from actual oral unit counts. Doses in ml, mg, drops, injections and unspecified nutrients are not converted automatically. “Fortified” classifies the whole food, not the added nutrient fraction.')}</p>{NUTRIENT_REFERENCES.map(reference => {
    const result = compareNutrientReference(reference, { age: profile?.age ?? null, sex: profile?.formulaSex ?? 'female', state: 'any' }, { food: summary.actual[reference.nutrient].value, supplement: fromCare(reference.nutrient, 'supplement'), medicine: fromCare(reference.nutrient, 'medicine'), unit: reference.unit });
    return <div key={reference.id}><h4>{t('Верхний допустимый уровень магния из БАДов и лекарств', 'Supplemental and medicinal magnesium upper limit')}</h4><p>{reference.value} {reference.unit}/{t('сутки', 'day')}, {t('с 19 лет; пищевой магний исключён', 'age 19+; food magnesium excluded')}. {result ? `${t('По записанным пероральным единицам', 'From logged oral units')}: ${fmt(result.value)} ${reference.unit} (${fmt(result.percent)}%).` : t('Для сравнения укажите применимый возраст в профиле.', 'Enter an applicable age in the profile to compare.')}</p>{result?.aboveUpperLimit && <p className="physis-warning">{t('Записанное количество выше справочного UL. Это не назначение и не основание самостоятельно менять терапию; уточните у врача.', 'The logged amount exceeds the reference UL. This does not prescribe treatment or justify changing therapy; discuss it with your clinician.')}</p>}<p><a href={reference.source} target="_blank" rel="noreferrer">{reference.organization}</a> · {reference.type} · {reference.version}</p></div>;
  })}<p className="physis-muted">{t('UL отличается от желательной нормы RDA/AI/PRI. Для остальных показателей нормы здесь не заданы: отсутствие UL не означает отсутствие риска. Неполные сведения не подтверждают безопасность.', 'UL differs from a desired RDA/AI/PRI level. Other references are not configured: no UL does not mean no risk. Incomplete data do not establish safety.')}</p></details>;
}

export function PhysisNutritionSummary(props: Props) {
  const t = tr(props.language);
  const date = todayCivilDate(props.context);
  const summary = summaryForDay(props.store, date);
  return <section className="physis-panel"><h3>{t('Питание сегодня', 'Nutrition today')}</h3>{summary.meals.some(meal => meal.data.status === 'actual') ? <NutrientSummary totals={summary.actual} props={props} compact /> : <p className="physis-muted">{t('Приёмы пищи ещё не записаны. Добавьте съеденное в рацион.', 'No meals logged yet. Add what you ate in the diary.')}</p>}<p className="physis-muted">{t('Сумма только по записанной еде; план и БАДы учитываются отдельно.', 'Logged food only; plans and supplements are tracked separately.')}</p></section>;
}

export function PhysisNutrition(props: Props & { page: 'today' | 'diary' | 'foods' | 'settings' }) {
  return <div className="physis-nutrition" data-page={props.page}>{props.page === 'foods' ? <FoodCatalog {...props} /> : props.page === 'settings' ? <NutritionSettings key={profileFor(props)?.updatedAt ?? 'new-profile'} {...props} /> : <NutritionDiary key={props.page} {...props} mode={props.page === 'today' ? 'today' : 'plan'} />}</div>;
}

function FoodCatalog(props: Props) {
  const t = tr(props.language);
  const actions = useActions();
  const [count, setCount] = useState(12);
  const [query, changeQuery] = useState('');
  const setQuery = (value: string) => { changeQuery(value); setCount(12); };
  const [onlyFavorites, changeFavorites] = useState(false);
  const setOnlyFavorites = (value: boolean) => { changeFavorites(value); setCount(12); };
  const [category, changeCategory] = useState('');
  const setCategory = (value: string) => { changeCategory(value); setCount(12); };
  const [nutrientFilter, changeNutrientFilter] = useState<NutrientKey | ''>('');
  const setNutrientFilter = (value: NutrientKey | '') => { changeNutrientFilter(value); setCount(12); };
  const [editing, setEditing] = useState<string | null>(null);
  const [recipeEditing, setRecipeEditing] = useState<string | null>(null);
  const [showImport, setShowImport] = useState(false);
  const catalog = catalogFor(props);
  const recent = new Set(physisRecords<Meal>(props.store, 'meal').sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 10).flatMap(record => record.data.items.map(item => item.foodId)));
  const visible = catalog.filter(entry => !entry.food.archived && (!category || (category === foodGroups[0] ? isTopFood(entry.food) : (entry.food.category || 'Другое') === category)) && (!onlyFavorites || entry.food.favorite) && (!nutrientFilter || (entry.food.nutrients[nutrientFilter]?.value ?? 0) > 0) && `${entry.food.name} ${entry.food.brand} ${entry.food.aliases.join(' ')}`.toLocaleLowerCase().includes(query.toLocaleLowerCase())).sort((a, b) => nutrientFilter ? (b.food.nutrients[nutrientFilter]?.value ?? 0) - (a.food.nutrients[nutrientFilter]?.value ?? 0) : Number(isTopFood(b.food)) - Number(isTopFood(a.food)) || Number(b.food.favorite) - Number(a.food.favorite) || Number(recent.has(b.id)) - Number(recent.has(a.id)) || a.food.name.localeCompare(b.food.name));
  async function saveFood(entry: CatalogEntry, food: Food) {
    await props.store.save(entry.record.kind === 'food' ? editPhysisRecord(entry.record as PhysisRecord<Food>, food) : editPhysisRecord(entry.record as PhysisRecord<Recipe>, { ...(entry.record.data as Recipe), food }));
  }
  return <>
    <section className="physis-panel physis-food-heading"><div className="physis-food-intro"><h2><button type="button" className="physis-heading-hint" aria-label={t('Список продуктов', 'Food catalog')} data-tooltip={t('База USDA SR Legacy и подборка из вашей таблицы. Указаны источник и состояние продукта; отсутствующие значения не заменяются нулями.', 'USDA SR Legacy data and a selection from your table. Sources and food states are identified; missing values are never replaced with zeros.')}>{t('Список продуктов', 'Food catalog')}</button></h2><p>{t('Создавайте свои продукты с этикетки, сохраняйте блюда и добавляйте любимые продукты в избранное.', 'Create foods from labels, save recipes and keep your favorites close.')}</p></div><div className="physis-actions"><button className="physis-primary" onClick={() => { setEditing('new'); setRecipeEditing(null); }}>{t('Создать продукт', 'Create food')}</button><button onClick={() => { setRecipeEditing('new'); setEditing(null); }}>{t('Создать рецепт', 'Create recipe')}</button><button onClick={() => setShowImport(!showImport)} aria-expanded={showImport}>{t('Импорт USDA JSON', 'Import USDA JSON')}</button></div><ErrorMessage error={actions.error} /></section>
    {showImport && <FoodImport props={props} onClose={() => setShowImport(false)} />}
    {editing && <FoodEditor key={editing} props={props} record={catalog.find(entry => entry.id === editing)?.record as PhysisRecord<Food> | undefined} onClose={() => setEditing(null)} />}
    {recipeEditing && <RecipeEditor key={recipeEditing} props={props} record={catalog.find(entry => entry.id === recipeEditing)?.record as PhysisRecord<Recipe> | undefined} onClose={() => setRecipeEditing(null)} />}
    <nav className="physis-food-category-nav" aria-label={t('Категории продуктов','Food categories')}><button className="physis-superfoods" aria-pressed={category === foodGroups[0]} onClick={() => setCategory(foodGroups[0])}>{foodGroups[0]}<small>{catalog.filter(entry => !entry.food.archived && isTopFood(entry.food)).length}</small></button><button aria-pressed={!category} onClick={() => setCategory('')}>{t('Все продукты','All foods')}</button>{foodGroups.slice(1).map(name => <button key={name} aria-pressed={category === name} onClick={() => setCategory(name)}>{name}</button>)}</nav>
    <section className="physis-panel"><div className="physis-form physis-nutrition-filters"><label>{t('Категория продуктов', 'Food category')}<select value={category} onChange={event => setCategory(event.target.value)}><option value="">{t('Все категории', 'All categories')}</option>{[...new Set([...foodGroups, ...catalog.map(entry => entry.food.category || 'Другое')])].map(name => <option key={name}>{name}</option>)}</select></label><label>{t('Поиск продуктов и блюд', 'Search foods and recipes')}<input value={query} onChange={event => setQuery(event.target.value)} type="search" /></label><label>{t('Состав с известным значением', 'Known nutrient content')}<select value={nutrientFilter} onChange={event => setNutrientFilter(event.target.value as NutrientKey | '')}><option value="">{t('Все продукты', 'All foods')}</option>{NUTRIENT_KEYS.map(key => <option key={key} value={key}>{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)}</option>)}</select></label><label className="physis-nutrition-check"><input type="checkbox" checked={onlyFavorites} onChange={event => setOnlyFavorites(event.target.checked)} />{t('Только избранное', 'Favorites only')}</label></div>
      {category === foodGroups[0] && <SuperfoodCollectionNote language={props.language} />}
      {!visible.length && <p className="physis-empty">{t('Продуктов пока нет или они не подходят под фильтры. Создайте продукт с нужной калорийностью и БЖУ.', 'No matching foods yet. Create a food with its calories and macros.')}</p>}
      <div className="physis-nutrition-catalog">{visible.slice(0, count).map(entry => <article key={entry.id}><div className="physis-row"><div><h3>{entry.food.name}</h3><p className="physis-muted">{entry.food.category || t('Другое', 'Other')} · {entry.food.brand}{entry.food.brand && ' · '}{entry.record.kind === 'recipe' ? t('Рецепт', 'Recipe') : entry.food.provenance.provider}{recent.has(entry.id) && ` · ${t('Недавний', 'Recent')}`}</p></div><button disabled={actions.busy} aria-pressed={entry.food.favorite} onClick={() => void actions.run(() => saveFood(entry, { ...entry.food, favorite: !entry.food.favorite }))}>{entry.food.favorite ? t('В избранном', 'Favorite') : t('В избранное', 'Add favorite')}</button></div><p>{t('На ', 'Per ')}{entry.food.basis === '100g' ? '100 g' : '100 ml'}: {core.slice(0, 4).map(key => `${t(NUTRIENTS[key].ru, NUTRIENTS[key].en)} ${fmt(entry.food.nutrients[key]?.value)} ${NUTRIENTS[key].unit}`).join(' · ')}</p><FoodReferenceNote food={entry.food} language={props.language} /><Warnings food={entry.food} props={props} /><ExpandableFoodDetails food={entry.food} props={props} /><div className="physis-actions"><button onClick={() => entry.record.kind === 'recipe' ? setRecipeEditing(entry.id) : setEditing(entry.id)}>{t('Редактировать', 'Edit')}</button><button disabled={actions.busy} onClick={() => void actions.run(() => saveFood(entry, { ...entry.food, archived: true }))}>{t('В архив', 'Archive')}</button></div></article>)}</div>
      {visible.length > count && <button type="button" onClick={() => setCount(value => value + 12)}>{t('Показать ещё', 'Show more')} ({visible.length - count})</button>}
      {catalog.some(entry => entry.food.archived) && <details><summary>{t('Архив продуктов', 'Archived foods')}</summary>{catalog.filter(entry => entry.food.archived).map(entry => <div className="physis-row" key={entry.id}><span>{entry.food.name}</span><button disabled={actions.busy} onClick={() => void actions.run(() => saveFood(entry, { ...entry.food, archived: false }))}>{t('Вернуть', 'Restore')}</button></div>)}</details>}
    </section>
  </>;
}

function ExpandableFoodDetails({ food, props }: { food: Food; props: Props }) {
  const [open, setOpen] = useState(false);
  const t = tr(props.language);
  return <details onToggle={event => setOpen(event.currentTarget.open)}><summary>{t('Порция и полный состав', 'Portion and full composition')}</summary>{open && <FoodDetails food={food} props={props} />}</details>;
}

function FoodDetails({ food, props }: { food: Food; props: Props }) {
  const t = tr(props.language);
  const [quantity, setQuantity] = useState('100');
  const value = physisNumber(quantity, .01, 100000);
  const totals = value === null ? null : totalNutrients([{ id: 'preview', foodId: 'preview', food, snapshotAt: new Date().toISOString(), quantity: value, unit: food.basis === '100g' ? 'g' : 'ml' }]);
  const difference = energyDifference(food);
  return <div><label className="physis-nutrition-portion">{t('Количество съедобной части', 'Edible amount')} ({food.basis === '100g' ? 'g' : 'ml'})<input inputMode="decimal" value={quantity} onChange={event => setQuantity(event.target.value)} /></label>{totals && <NutrientSummary totals={totals} props={props} full />}<p>{t('Состав', 'Ingredients')}: {food.ingredients || t('не указан', 'not specified')}</p><p>{t('Источник', 'Source')}: {food.provenance.source.startsWith('https://') ? <a href={food.provenance.source} target="_blank" rel="noreferrer">{food.provenance.source}</a> : food.provenance.source} · {food.provenance.version} · {food.provenance.license}</p><p>{t('Съедобная часть', 'Edible fraction')}: {fmt(food.edibleFraction * 100)}%. {t('В дневнике вводите массу уже съедобной части.', 'Log the edible portion weight.')}</p>{difference !== null && Math.abs(difference) > Math.max(10, (food.nutrients.energy?.value ?? 0) * .1) && <p className="physis-warning">{t('Энергия источника отличается от 4×Б + 9×Ж + 4×У на ', 'Source energy differs from 4P + 9F + 4C by ')}{fmt(difference)} kcal. {t('Сохраняем значение источника: клетчатка, полиолы, коэффициенты и округление могут давать различия.', 'The source value is retained: fiber, polyols, factors and rounding can explain differences.')}</p>}<details><summary>{t('Качество и источники нутриентов', 'Nutrient quality and sources')}</summary>{NUTRIENT_KEYS.map(key => <p key={key}>{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)}: {food.nutrients[key]?.quality ?? 'unknown'} · {food.nutrients[key]?.source ?? t('нет данных', 'no data')}</p>)}</details></div>;
}

function FoodEditor({ props, record, onClose }: { props: Props; record?: PhysisRecord<Food>; onClose: () => void }) {
  const t = tr(props.language);
  const actions = useActions();
  const [food, setFood] = useState<Food>(() => structuredClone(record?.data ?? blankFood()));
  const [draftRecord] = useState(() => record ?? newPhysisRecord('food', food));
  const [values, setValues] = useState<Record<string, string>>(() => Object.fromEntries(NUTRIENT_KEYS.map(key => [key, record?.data.nutrients[key]?.quality === 'trace' ? 'trace' : String(record?.data.nutrients[key]?.value ?? '')])));
  const [serving, setServing] = useState(String(food.servingAmount));
  const [density, setDensity] = useState(String(food.densityGPerMl ?? ''));
  const [edible, setEdible] = useState(String(food.edibleFraction * 100));
  async function save() {
    const servingAmount = physisNumber(serving, .01, 100000), ediblePercent = physisNumber(edible, .01, 100), densityGPerMl = density.trim() ? physisNumber(density, .001, 30) : null;
    if (servingAmount === null || ediblePercent === null || (density.trim() && densityGPerMl === null)) throw new Error(t('Проверьте порцию, плотность и съедобную часть.', 'Check serving, density and edible fraction.'));
    const nutrients = Object.fromEntries(NUTRIENT_KEYS.map(key => {
      const text = values[key].trim();
      const trace = /^(trace|следы)$/i.test(text);
      const amount = !text || trace ? null : physisNumber(text, 0, 1e7);
      if (text && !trace && amount === null) throw new Error(`${t('Некорректное значение', 'Invalid value')}: ${t(NUTRIENTS[key].ru, NUTRIENTS[key].en)}`);
      const old = record?.data.nutrients[key];
      const unchanged = old && amount === old.value && food.basis === record?.data.basis && food.provenance.source === record?.data.provenance.source && food.provenance.version === record?.data.provenance.version && !trace;
      return [key, unchanged ? old : nutrient(amount, key, food.basis, food.provenance.source, food.provenance.version, trace ? 'trace' : undefined)];
    }));
    const next = { ...food, name: food.name.trim(), nutrients, servingAmount, densityGPerMl, edibleFraction: ediblePercent / 100 };
    await validateAndSave(props, editPhysisRecord(draftRecord, next)); onClose();
  }
  function fields(keys: NutrientKey[]) { return keys.map(key => <label key={key}>{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)} ({NUTRIENTS[key].unit})<input inputMode="decimal" value={values[key]} onChange={event => setValues({ ...values, [key]: event.target.value })} placeholder={t('Неизвестно', 'Unknown')} /></label>); }
  return <section className="physis-panel"><h3>{record ? t('Редактировать продукт', 'Edit food') : t('Новый продукт', 'New food')}</h3><form className="physis-form" onSubmit={event => { event.preventDefault(); void actions.run(save); }}><label>{t('Название', 'Name')}<input required maxLength={500} value={food.name} onChange={event => setFood({ ...food, name: event.target.value })} /></label><label>{t('Категория продукта', 'Food category')}<input list="physis-food-groups" maxLength={80} value={food.category || ''} onChange={event => setFood({ ...food, category: event.target.value })} /><datalist id="physis-food-groups">{foodGroups.map(name => <option key={name} value={name} />)}</datalist></label><label>{t('Бренд / вариант', 'Brand / variant')}<input maxLength={200} value={food.brand} onChange={event => setFood({ ...food, brand: event.target.value })} /></label><label>{t('Синонимы через запятую', 'Aliases, comma separated')}<input value={food.aliases.join(', ')} onChange={event => setFood({ ...food, aliases: event.target.value.split(',').map(alias => alias.trim()) })} /></label><label>{t('Базис состава', 'Nutrition basis')}<select value={food.basis} onChange={event => setFood({ ...food, basis: event.target.value as Food['basis'] })}><option value="100g">100 g</option><option value="100ml">100 ml</option></select></label><label>{t('Состояние', 'State')}<select value={food.state} onChange={event => setFood({ ...food, state: event.target.value as Food['state'] })}>{(['raw', 'cooked', 'dry', 'reconstituted', 'unknown'] as const).map((state, index) => <option key={state} value={state}>{t(['Сырой', 'Приготовленный', 'Сухой', 'Восстановленный', 'Неизвестно'][index], ['Raw', 'Cooked', 'Dry', 'Reconstituted', 'Unknown'][index])}</option>)}</select></label><div className="physis-nutrition-fields">{fields(core)}</div><details><summary>{t('Сахара, жирные кислоты, витамины и минералы', 'Sugars, fatty acids, vitamins and minerals')}</summary><div className="physis-nutrition-fields">{fields(NUTRIENT_KEYS.filter(key => !core.includes(key)))}</div></details><p className="physis-muted">{t('Пусто = нет данных; 0 = подтверждённый ноль. Для следовых количеств введите «trace». Энергия с этикетки сохраняется отдельно от расчёта 4/9/4.', 'Blank means unknown; 0 means confirmed zero. Enter “trace” for trace amounts. Label energy is preserved separately from 4/9/4 calculations.')}</p><div className="physis-nutrition-fields"><label>{t('Размер порции', 'Serving size')} ({food.basis === '100g' ? 'g' : 'ml'})<input inputMode="decimal" required value={serving} onChange={event => setServing(event.target.value)} /></label><label>{t('Название порции', 'Serving name')}<input value={food.servingName} onChange={event => setFood({ ...food, servingName: event.target.value })} /></label><label>{t('Плотность, только известная', 'Density, only if known')} (g/ml)<input inputMode="decimal" value={density} onChange={event => setDensity(event.target.value)} placeholder={t('Неизвестно', 'Unknown')} /></label><label>{t('Съедобная часть, %', 'Edible fraction, %')}<input inputMode="decimal" value={edible} onChange={event => setEdible(event.target.value)} /></label></div><label>{t('Ингредиенты', 'Ingredients')}<textarea value={food.ingredients} maxLength={10000} onChange={event => setFood({ ...food, ingredients: event.target.value })} /></label><label className="physis-nutrition-check"><input type="checkbox" checked={food.compositionKnown} onChange={event => setFood({ ...food, compositionKnown: event.target.checked })} />{t('Состав известен полностью', 'Complete composition known')}</label><fieldset><legend>{t('Категории — отметьте по составу', 'Categories — classify from ingredients')}</legend>{(Object.keys(categoryNames) as FoodCategory[]).map(category => <label key={category}>{t(...categoryNames[category])}<select value={food.contains.includes(category) ? 'contains' : food.mayContain.includes(category) ? 'mayContain' : 'none'} onChange={event => setFood({ ...food, contains: [...food.contains.filter(item => item !== category), ...(event.target.value === 'contains' ? [category] : [])], mayContain: [...food.mayContain.filter(item => item !== category), ...(event.target.value === 'mayContain' ? [category] : [])] })}><option value="none">{food.compositionKnown ? t('Не содержит', 'Absent') : t('Не установлено', 'Not established')}</option><option value="contains">{t('Содержит', 'Contains')}</option><option value="mayContain">{t('Может содержать', 'May contain')}</option></select></label>)}</fieldset><p className="physis-muted">{t('Бобовые включают фасоль, горох, нут, чечевицу, сою, арахис, люпин и другие виды. «Растительное масло» не устанавливает вид сырья. Масла из семян не равны частично гидрогенизированным жирам.', 'Legumes include beans, peas, chickpeas, lentils, soy, peanuts, lupins and other species. “Vegetable oil” does not identify the source. Seed oils are distinct from partially hydrogenated fats.')}</p>{food.contains.includes('legume') && <label>{t('Обработка бобовых', 'Legume preparation')}<select value={food.legumePreparation === 'not-applicable' ? 'unknown' : food.legumePreparation} onChange={event => setFood({ ...food, legumePreparation: event.target.value as Food['legumePreparation'] })}><option value="unknown">{t('Не подтверждена', 'Unknown')}</option><option value="adequately-cooked">{t('Достаточно приготовлены', 'Adequately cooked')}</option><option value="undercooked">{t('Сырые / недоваренные', 'Raw / undercooked')}</option></select></label>}<label className="physis-nutrition-check"><input type="checkbox" checked={food.fortified} onChange={event => setFood({ ...food, fortified: event.target.checked })} />{t('Обогащённый продукт', 'Fortified food')}</label><label className="physis-nutrition-check"><input type="checkbox" checked={food.favorite} onChange={event => setFood({ ...food, favorite: event.target.checked })} />{t('Добавить в избранное', 'Add to favorites')}</label><label>{t('Источник состава / этикетка', 'Source / label')}<input required maxLength={1000} value={food.provenance.source} onChange={event => setFood({ ...food, provenance: { ...food.provenance, provider: 'label', source: event.target.value } })} /></label><label>{t('Версия / дата этикетки', 'Version / label date')}<input required value={food.provenance.version} onChange={event => setFood({ ...food, provenance: { ...food.provenance, version: event.target.value } })} /></label><ErrorMessage error={actions.error} /><div className="physis-actions"><button className="physis-primary" disabled={actions.busy} type="submit">{actions.busy ? t('Сохраняется…', 'Saving…') : t('Сохранить продукт', 'Save food')}</button><button type="button" disabled={actions.busy} onClick={onClose}>{t('Отмена', 'Cancel')}</button></div></form></section>;
}

function FoodImport({ props, onClose }: { props: Props; onClose: () => void }) {
  const t = tr(props.language); const actions = useActions();
  const [raw, setRaw] = useState(''); const [preview, setPreview] = useState<Food | null>(null);
  const [pendingUsda, setPendingUsda] = useState<string | null>(null);
  const duplicate = preview && pendingUsda !== preview.provenance.id && catalogFor(props).some(entry => entry.food.provenance.provider === 'USDA' && entry.food.provenance.id === preview.provenance.id);
  return <section className="physis-panel"><h3>{t('Импорт FoodData Central', 'FoodData Central import')}</h3><p>{t('Вставьте JSON одного продукта из официального USDA API. Запросы к поставщику здесь не отправляются. Другие записи Фюзиса импортируются в общих настройках.', 'Paste one food JSON from the official USDA API. This form makes no provider requests. Import other Physis records in general settings.')}</p><label>{t('JSON продукта', 'Food JSON')}<textarea rows={6} value={raw} maxLength={1000000} onChange={event => { setRaw(event.target.value); setPreview(null); }} /></label><div className="physis-actions"><button disabled={actions.busy} onClick={() => void actions.run(() => { const food = importUsdaFood(JSON.parse(raw)); if (!validateNutritionRecord(newPhysisRecord('food', food))) throw new Error(t('Некорректный состав', 'Invalid composition')); setPreview(food); })}>{t('Предварительный просмотр', 'Preview')}</button><button onClick={onClose}>{t('Закрыть', 'Close')}</button></div>{preview && <><h4>{preview.name}</h4><p>{preview.provenance.version} · {preview.provenance.license}</p><p>{t('Импортировано нутриентов', 'Nutrients found')}: {Object.keys(preview.nutrients).length}. {t('Классификацию ингредиентов проверьте после импорта.', 'Review ingredient classification after import.')}</p>{duplicate && <p className="physis-warning">{t('Такой USDA ID уже есть в каталоге. Повторный импорт пропущен.', 'This USDA ID already exists. Duplicate import is skipped.')}</p>}<button className="physis-primary" disabled={actions.busy || !!duplicate} onClick={() => void actions.run(async () => { setPendingUsda(preview.provenance.id); await actions.submitCreation(`usda:${preview.provenance.id}`, () => [{ ...newPhysisRecord('food', preview), source: 'import' }], props.store); onClose(); })}>{t('Импортировать продукт', 'Import food')}</button></>}<ErrorMessage error={actions.error} /></section>;
}

function IngredientPicker({ props, items, onChange }: { props: Props; items: MealItem[]; onChange: (items: MealItem[]) => void }) {
  const t = tr(props.language); const [query, setQuery] = useState(''); const [selected, setSelected] = useState('');
  const [quantity, setQuantity] = useState('100'); const [unit, setUnit] = useState<MealItem['unit']>('g');
  const [error, setError] = useState(''); const [onlyFavorites, setOnlyFavorites] = useState(false);
  const catalog = catalogFor(props).filter(entry => !entry.food.archived);
  const recent = new Set(physisRecords<Meal>(props.store, 'meal').sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 10).flatMap(record => record.data.items.map(item => item.foodId)));
  const visible = catalog.filter(entry => (!onlyFavorites || entry.food.favorite) && `${entry.food.name} ${entry.food.brand} ${entry.food.aliases.join(' ')}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => Number(isTopFood(b.food)) - Number(isTopFood(a.food)) || Number(b.food.favorite) - Number(a.food.favorite) || Number(recent.has(b.id)) - Number(recent.has(a.id)) || a.food.name.localeCompare(b.food.name));
  const food = catalog.find(entry => entry.id === selected);
  return <div className="physis-nutrition-picker"><div className="physis-nutrition-fields"><label>{t('Поиск продукта или блюда', 'Find food or recipe')}<input type="search" value={query} onChange={event => setQuery(event.target.value)} /></label><label className="physis-nutrition-check"><input type="checkbox" checked={onlyFavorites} onChange={event => setOnlyFavorites(event.target.checked)} />{t('Избранное', 'Favorites')}</label><label>{t('Продукт', 'Food')}<select value={selected} onChange={event => { setSelected(event.target.value); const entry = catalog.find(item => item.id === event.target.value); setUnit(entry?.food.basis === '100ml' ? 'ml' : 'g'); }}><option value="">{t('Выберите продукт', 'Select food')}</option>{visible.map(entry => <option key={entry.id} value={entry.id}>{entry.food.favorite ? `${t('Избранное', 'Favorite')} · ` : recent.has(entry.id) ? `${t('Недавний', 'Recent')} · ` : ''}{entry.food.name}</option>)}</select></label><label>{t('Количество', 'Amount')}<input inputMode="decimal" value={quantity} onChange={event => setQuantity(event.target.value)} /></label><label>{t('Единица', 'Unit')}<select value={unit} onChange={event => setUnit(event.target.value as MealItem['unit'])}><option value="g">g</option><option value="ml">ml</option><option value="serving">{t('Порция', 'Serving')}{food ? ` (${food.food.servingAmount} ${food.food.basis === '100g' ? 'g' : 'ml'})` : ''}</option></select></label></div>{!catalog.length && <p className="physis-empty">{t('Сначала создайте свои продукты или добавьте стартовый набор в «Списке продуктов».', 'Create foods or add the starter set in the food catalog first.')}</p>}{food && <Warnings food={food.food} props={props} />}<button type="button" onClick={() => { setError(''); try { const amount = physisNumber(quantity, .01, 100000); if (!food || amount === null) throw new Error(t('Выберите продукт и положительное количество.', 'Select a food and enter a positive amount.')); onChange([...items, snapshotItem(food.id, food.food, amount, unit)]); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Error'); } }}>{t('Добавить в состав', 'Add item')}</button><ErrorMessage error={error} /><div className="physis-nutrition-items">{items.map((item, index) => <div key={item.id}><div className="physis-row"><span><strong>{item.food.name}</strong> · {fmt(item.quantity)} {item.unit === 'serving' ? t('порц.', 'servings') : item.unit}</span><div className="physis-actions"><button type="button" disabled={index === 0} aria-label={`${t('Выше', 'Move up')}: ${item.food.name}`} onClick={() => { const next = [...items]; [next[index - 1], next[index]] = [next[index], next[index - 1]]; onChange(next); }}>{t('Выше', 'Up')}</button><button type="button" aria-label={`${t('Убрать', 'Remove')}: ${item.food.name}`} onClick={() => onChange(items.filter(entry => entry.id !== item.id))}>{t('Убрать', 'Remove')}</button></div></div><label>{t('Изменить количество', 'Edit amount')}<input type="text" inputMode="decimal" defaultValue={String(item.quantity)} onChange={event => { const amount = physisNumber(event.target.value, .01, 100000); const message = amount === null ? t('Количество должно быть положительным числом.', 'Amount must be positive.') : ''; event.target.setCustomValidity(message); setError(message); if (amount !== null) onChange(items.map(entry => entry.id === item.id ? { ...entry, quantity: amount } : entry)); }} /></label></div>)}</div></div>;
}

function RecipeEditor({ props, record, onClose }: { props: Props; record?: PhysisRecord<Recipe>; onClose: () => void }) {
  const t = tr(props.language); const actions = useActions();
  const [draftRecord] = useState(() => record ?? newPhysisRecord('recipe', {}));
  const [name, setName] = useState(record?.data.name ?? ''); const [items, setItems] = useState<MealItem[]>(record?.data.ingredients ?? []);
  const [yieldValue, setYield] = useState(String(record?.data.yieldGrams ?? '')); const [servings, setServings] = useState(String(record?.data.servings ?? 1)); const [note, setNote] = useState(record?.data.note ?? '');
  return <section className="physis-panel"><h3>{t('Рецепт и выход блюда', 'Recipe and final yield')}</h3><form className="physis-form" onSubmit={event => { event.preventDefault(); void actions.run(async () => {
    const yieldGrams = physisNumber(yieldValue, .01, 1e6), count = physisNumber(servings, .01, 10000);
    if (yieldGrams === null || count === null) throw new Error(t('Укажите массу готового блюда и число порций.', 'Enter final cooked weight and serving count.'));
    const food = recipeFood(name.trim(), items, yieldGrams, count);
    food.favorite = record?.data.food.favorite ?? false;
    const data: Recipe = { name: name.trim(), ingredients: items, yieldGrams, servings: count, note, food };
    await validateAndSave(props, editPhysisRecord(draftRecord, data)); onClose();
  }); }}><label>{t('Название блюда', 'Recipe name')}<input required value={name} onChange={event => setName(event.target.value)} maxLength={500} /></label><IngredientPicker props={props} items={items} onChange={setItems} /><div className="physis-nutrition-fields"><label>{t('Выход готового блюда, г', 'Final cooked yield, g')}<input required inputMode="decimal" value={yieldValue} onChange={event => setYield(event.target.value)} /></label><label>{t('Число порций', 'Servings')}<input required inputMode="decimal" value={servings} onChange={event => setServings(event.target.value)} /></label></div><label>{t('Приготовление / заметка', 'Preparation / note')}<textarea value={note} onChange={event => setNote(event.target.value)} maxLength={10000} /></label><p className="physis-muted">{t('Вода и уварка меняют состав на 100 г. Расчёт использует исходные ингредиенты без предположений о сохранности витаминов. Для варёных бобовых выбирайте приготовленные ингредиенты с известной обработкой.', 'Water and cooking loss change values per 100 g. Values are calculated from ingredients without assumed vitamin retention. For cooked legumes, select prepared ingredients with known preparation.')}</p>{items.length > 0 && <NutrientSummary totals={totalNutrients(items)} props={props} />}<ErrorMessage error={actions.error} /><div className="physis-actions"><button disabled={actions.busy} className="physis-primary" type="submit">{t('Сохранить рецепт', 'Save recipe')}</button><button disabled={actions.busy} type="button" onClick={onClose}>{t('Отмена', 'Cancel')}</button></div></form></section>;
}

function NutritionMealDialog({children,onClose,language,title}: {children:ReactNode;onClose:()=>void;language:string;title?:string}) {
 const ref=useDialogAccessibility<HTMLElement>(onClose,true);
 return <div className="modal-backdrop physis-settings-backdrop"><section ref={ref} className="modal physis-settings-dialog physis-meal-dialog" role="dialog" tabIndex={-1} aria-modal="true" aria-label={title ?? tr(language)('Изменить приём пищи','Edit meal')}><header className="physis-settings-heading"><h2>{title ?? tr(language)('Изменить приём пищи','Edit meal')}</h2><DialogCloseButton aria-label={tr(language)('Закрыть','Close')} onClick={onClose} /></header><div className="physis-settings-content">{children}</div></section></div>;
}

function NutritionPlanWizard({ props, open, onClose, dates }: { props: Props; open: boolean; onClose: () => void; dates: string[] }) {
  const t = tr(props.language), actions = useActions();
  const ref = useDialogAccessibility<HTMLElement>(()=>{if(!actions.busy)onClose();}, open);
  const existingProfile = profileFor(props);
  const [profile, setProfile] = useState(() => structuredClone(existingProfile?.data ?? { ...defaultNutritionProfile(), goal: 'maintain' as const }));
  const [profileRecord] = useState(() => existingProfile ?? newPhysisRecord('nutrition-profile', profile));
  const [parameters, setParameters] = useState({ age: String(profile.age ?? ''), heightCm: String(profile.heightCm ?? ''), weightKg: String(profile.weightKg ?? ''), activityFactor: String(profile.activityFactor) });
  const [step, setStep] = useState(0);
  const [energy, setEnergy] = useState('');
  const [shares, setShares] = useState({ protein: '20', fat: '30', carbohydrate: '50' });
  const [basis, setBasis] = useState('');
  const [target, setTarget] = useState<NutritionTarget | undefined>();
  const [targetScope,setTargetScope]=useState<'both'|'rest'|'training'>('both');
  const [day, setDay] = useState(dates[0]);
  const blankMeals = (date: string): Meal[] => [
    [t('Завтрак','Breakfast'),'08:00'],[t('Обед','Lunch'),'12:00'],[t('Полдник','Afternoon snack'),'16:00'],[t('Ужин','Dinner'),'19:00'],
  ].map(([name,time]) => ({date,time,name,timeZone:props.settings.timeZone,status:'planned',items:[],note:''}));
  const [drafts, setDrafts] = useState<Record<string, Meal[]>>({});
  const [mealIndex, setMealIndex] = useState(0);
  const [newFood, setNewFood] = useState(false);
  const meals = drafts[day] ?? blankMeals(day);
  const prepared = Object.values(drafts).flat().filter(meal => meal.items.length);
  const updateMeal = (index: number, patch: Partial<Meal>) => setDrafts(current => ({ ...current, [day]: meals.map((meal,i) => i === index ? { ...meal,...patch } : meal) }));
  const readParameters = (optional=false) => {
    const age = physisNumber(parameters.age,0,120), heightCm = physisNumber(parameters.heightCm,1,250), weightKg = physisNumber(parameters.weightKg,1,400), activityFactor = physisNumber(parameters.activityFactor,1,2.5);
    if ((!optional && (age === null || heightCm === null || weightKg === null)) || (optional && ((parameters.age.trim() && age === null) || (parameters.heightCm.trim() && heightCm === null) || (parameters.weightKg.trim() && weightKg === null))) || activityFactor === null) throw new Error(t('Заполните возраст, рост, массу и активность.','Enter age, height, weight and activity.'));
    return { ...profile,age,heightCm,weightKg,activityFactor };
  };
  return <div className="modal-backdrop physis-settings-backdrop" hidden={!open}>
    <section ref={ref} className="modal physis-settings-dialog physis-plan-dialog" role="dialog" tabIndex={-1} aria-modal="true" aria-labelledby="physis-plan-title">
      <header className="physis-settings-heading"><div><h2 id="physis-plan-title">{t('Составить рацион','Build nutrition plan')}</h2><p className="physis-muted">{[t('Ваши данные','Your details'),t('Стартовые нормы','Starting targets'),t('Продукты и порции','Foods and portions'),t('Проверка рациона','Review plan')][step]}</p></div><DialogCloseButton aria-label={t('Закрыть','Close')} onClick={() => { if (!actions.busy) onClose(); }} /></header>
      <div className="physis-settings-content">
        <ol className="physis-wizard-steps" aria-label={t('Шаги составления рациона','Nutrition planning steps')}>{[t('Данные','Details'),t('Нормы','Targets'),t('Рацион','Meals'),t('Проверка','Review')].map((name,index) => <li key={name} aria-current={index === step ? 'step' : undefined}>{name}</li>)}</ol>
        {step === 0 && <section><h3>{t('Данные и цель','Details and goal')}</h3><div className="physis-form">{(['age','heightCm','weightKg','activityFactor'] as const).map((key,index) => <label key={key}>{[t('Возраст, лет','Age, years'),t('Рост, см','Height, cm'),t('Масса, кг','Weight, kg'),t('Коэффициент активности (1–2,5)','Activity factor (1–2.5)')][index]}<input inputMode="decimal" value={parameters[key]} onChange={event => setParameters({...parameters,[key]:event.target.value})} /></label>)}<label>{t('Параметр формулы','Formula parameter')}<select value={profile.formulaSex} onChange={event => setProfile({...profile,formulaSex:event.target.value as NutritionProfile['formulaSex']})}><option value="female">{t('Женский (−161)','Female (−161)')}</option><option value="male">{t('Мужской (+5)','Male (+5)')}</option></select></label><label>{t('Цель','Goal')}<select value={profile.goal} onChange={event => setProfile({...profile,goal:event.target.value as NutritionProfile['goal']})}>{(['maintain','lose','gain','custom'] as const).map((id,index) => <option value={id} key={id}>{[t('Поддержание','Maintain'),t('Снижение массы','Lose weight'),t('Набор','Gain weight'),t('Своя цель','Custom')][index]}</option>)}</select></label></div><label className="physis-check"><input type="checkbox" checked={profile.excluded} onChange={event => setProfile({...profile,excluded:event.target.checked})} />{t('Беременность, лактация или другая ситуация вне области взрослой формулы','Pregnancy, lactation or another situation outside the adult formula')}</label>
          <div className="physis-actions"><button className="physis-primary" disabled={actions.busy || profile.excluded || profile.goal === 'custom'} onClick={() => void actions.run(() => { const next=readParameters(), result=startingNutritionTargets(next); setProfile({...next,method:'mifflin-st-jeor',formulaVersion:result.estimate.version,formulaSource:result.estimate.source}); setEnergy(String(result.target.energy)); setBasis(`${t('Расчётное поддержание','Estimated maintenance')}: ${fmt(result.estimate.maintenance)} kcal · ${t('Поправка цели','Goal adjustment')}: ${Math.round((result.adjustment-1)*100)}%`); setStep(1); })}>{t('Рассчитать нормы','Calculate targets')}</button><button onClick={() => void actions.run(()=>{ const next=readParameters(true);setBasis(t('Нормы вводятся вручную.','Targets are entered manually.')); setEnergy(profile.rest.energy > 0 ? String(profile.rest.energy) : ''); setProfile({...next,method:'manual',formulaVersion:'manual v1',formulaSource:t('Пользователь','User')}); setStep(1); })}>{t('Ввести нормы вручную','Enter targets manually')}</button></div></section>}
        {step === 1 && <section><h3>{t('Рекомендуемый стартовый ориентир','Suggested starting point')}</h3><p>{basis}</p><p className="physis-muted">{t('Оценка по Mifflin–St Jeor. Поправка GENESIS: снижение −10%, поддержание 0%, набор +10%. Это редактируемый стартовый ориентир, а не измеренный обмен.','Mifflin–St Jeor estimate. GENESIS starting adjustment: loss −10%, maintenance 0%, gain +10%. Editable starting point, not measured metabolism.')}</p><div className="physis-form"><label>{t('Калорийность, ккал','Energy, kcal')}<input inputMode="decimal" value={energy} onChange={event => setEnergy(event.target.value)} /></label>{(['protein','fat','carbohydrate'] as const).map(key => <label key={key}>{t(NUTRIENTS[key].ru,NUTRIENTS[key].en)} (%)<input inputMode="decimal" value={shares[key]} onChange={event => setShares({...shares,[key]:event.target.value})} /><small>{Number.isFinite(Number(energy)*Number(shares[key])) ? fmt(Number(energy)*Number(shares[key])/100/(key === 'fat' ? 9 : 4)) : '—'} g</small></label>)}</div><label>{t('Применить дневные нормы','Apply daily targets')}<select value={targetScope} onChange={event=>setTargetScope(event.target.value as typeof targetScope)}><option value="both">{t('Ко всем дням','All days')}</option><option value="rest">{t('Только восстановительные дни','Rest days only')}</option><option value="training">{t('Только тренировочные дни','Training days only')}</option></select></label><details><summary>{t('Основание расчёта','Calculation basis')}</summary><p>{t('Стартовое распределение: белки 20%, жиры 30%, углеводы 50% энергии. Доли можно изменить; сумма должна составлять 100%.','Starting distribution: protein 20%, fat 30%, carbohydrate 50% of energy. Adjust the shares; they must total 100%.')}</p><a href="https://www.ncbi.nlm.nih.gov/books/NBK208874/" target="_blank" rel="noreferrer">DRI / AMDR</a></details><button className="physis-primary" onClick={() => void actions.run(() => { const kcal=physisNumber(energy,1,50000); if(kcal === null) throw new Error(t('Укажите калорийность.','Enter energy target.')); if(profile.method !== 'manual' && kcal < 1000) throw new Error(t('Автоматическая оценка ниже 1000 ккал не предлагается. Проверьте параметры','Automatic targets below 1000 kcal are not offered')); const values=Object.fromEntries(Object.entries(shares).map(([key,value])=>[key,physisNumber(value,0,100)])); if(Object.values(values).some(value=>value===null)) throw new Error(t('Проверьте доли БЖУ.','Check macro shares.')); setTarget(resolveTargets({mode:'calories',unit:'energy-percent',energy:kcal,protein:values.protein!,fat:values.fat!,carbohydrate:values.carbohydrate!,weightKg:profile.weightKg,fiber:14*kcal/1000})); setStep(2); })}>{t('Перейти к продуктам','Choose foods')}</button></section>}
        {step === 2 && target && <section><div className="physis-form"><label>{t('День рациона','Plan date')}<select value={day} onChange={event => {setDay(event.target.value);setMealIndex(0);}}>{dates.map(date => <option key={date} value={date}>{formatCalendarDateValue(date,props.settings.calendarMode,false,props.context)}</option>)}</select></label><label>{t('Приём пищи','Meal')}<select value={mealIndex} onChange={event=>setMealIndex(Number(event.target.value))}>{meals.map((meal,index)=><option key={index} value={index}>{meal.name}</option>)}</select></label></div><div className="physis-actions"><button onClick={() => {setDrafts(current=>({...current,[day]:[...meals,{...blankMeals(day)[0],name:t('Мой приём пищи','My meal')}]}));setMealIndex(meals.length);}}>{t('Добавить приём пищи','Add meal')}</button><button onClick={()=>setNewFood(!newFood)} aria-expanded={newFood}>{t('Создать свой продукт','Create your own food')}</button></div>
          {newFood && <FoodEditor props={props} onClose={()=>setNewFood(false)} />}
          <div className="physis-form"><label>{t('Название приёма','Meal name')}<input value={meals[mealIndex].name} maxLength={200} onChange={event=>updateMeal(mealIndex,{name:event.target.value})} /></label><label>{t('Время','Time')}<TimeClockPicker value={meals[mealIndex].time} onChange={time=>updateMeal(mealIndex,{time})} ariaLabel={t('Время приёма пищи','Meal time')} /></label></div><IngredientPicker key={`${day}:${mealIndex}`} props={props} items={meals[mealIndex].items} onChange={items=>updateMeal(mealIndex,{items})} /><NutrientSummary totals={totalNutrients(meals.flatMap(meal=>meal.items))} target={target} props={props} /><details><summary>{t('Подобрать порцию к цели','Plan a portion toward your target')}</summary><PortionPlanner props={props} totals={totalNutrients(meals.flatMap(meal=>meal.items))} target={target} date={day} empty={!meals.some(meal=>meal.items.length)} onAdd={item=>updateMeal(mealIndex,{items:[...meals[mealIndex].items,item]})} /></details>
          {dates.length > 1 && <button disabled={!meals.some(meal=>meal.items.length)} onClick={()=>setDrafts(current=>({...current,...Object.fromEntries(dates.map(date=>[date,meals.map(meal=>copyMeal(meal,date))]))}))}>{t('Повторить этот день на весь период','Repeat this day across the period')}</button>}
          <button className="physis-primary" disabled={!prepared.length} onClick={()=>setStep(3)}>{t('Проверить рацион','Review nutrition plan')}</button></section>}
        {step === 3 && target && <section><h3>{t('Проверьте план перед сохранением','Review the plan before saving')}</h3><p>{prepared.length} {t('приёмов пищи','meals')} · {new Set(prepared.map(meal=>meal.date)).size} {t('дней','days')}</p><p>{t('Дневная цель','Daily target')}: {fmt(target.energy)} kcal · {t('Б/Ж/У','P/F/C')} {fmt(target.protein)}/{fmt(target.fat)}/{fmt(target.carbohydrate)} g</p><ul className="physis-list">{dates.filter(date=>drafts[date]?.some(meal=>meal.items.length)).map(date=><li key={date}><strong>{formatCalendarDateValue(date,props.settings.calendarMode,false,props.context)}</strong>{drafts[date].filter(meal=>meal.items.length).map((meal,index)=><p key={index}>{meal.time} · {meal.name} · {meal.items.length} {t('продуктов','foods')}</p>)}</li>)}</ul><p className="physis-muted">{t('Рацион добавится как план. Существующие записи сохраняются; съеденное отмечается отдельно в «Сегодня».','Meals are added as a plan. Existing records are preserved; mark actual meals in Today.')}</p><button className="physis-primary" disabled={actions.busy} onClick={()=>void actions.run(async()=>{if(prepared.some(meal=>!meal.name.trim())) throw new Error(t('Укажите названия приёмов пищи.','Enter meal names.'));const current=profileFor(props) ?? profileRecord;const next={...current.data,...profile,foodRules:current.data.foodRules,selectedNutrients:current.data.selectedNutrients,mode:'calories' as const,macroUnit:'g' as const,rest:targetScope==='training'?current.data.rest:target,training:targetScope==='rest'?current.data.training:target};await actions.submitCreation('wizard-plan',()=>[editPhysisRecord(current,next),...prepared.map(meal=>newPhysisRecord('meal',meal))],props.store);setDrafts({});setStep(0);onClose();})}>{actions.busy ? t('Сохраняется…','Saving…') : t('Сохранить рацион','Save nutrition plan')}</button></section>}
        <ErrorMessage error={actions.error} />{step > 0 && <button disabled={actions.busy} onClick={()=>setStep(current=>current-1)}>{t('Назад','Back')}</button>}
      </div>
    </section>
  </div>;
}

function NutritionDiary(props: Props & { mode: 'today' | 'plan' }) {
  const t = tr(props.language); const actions = useActions();
  const [wizardOpen,setWizardOpen] = useState(false);
  const [selectedDate, setDate] = useState(() => todayCivilDate(props.context));
  const date = props.mode === 'today' ? todayCivilDate(props.context) : selectedDate;
  const planning = props.mode === 'plan';
  const [anchor, setAnchor] = useState(() => todayCivilDate(props.context));
  const previousCalendar = useRef(props.settings.calendarMode);
  useEffect(() => {
    if (previousCalendar.current !== props.settings.calendarMode) {
      previousCalendar.current = props.settings.calendarMode; setAnchor(date);
    }
  }, [date, props.settings.calendarMode]);
  const [period, setPeriod] = useState<'day' | 'week' | 'month'>('day');
  const { start: rangeStart, end: rangeEnd } = nutritionPeriodRange(period === 'day' ? date : anchor, props.settings.calendarMode, period, props.context);
  const cycleLabel = props.settings.calendarMode === 'sacred' ? t('Пята', 'Five-day period') : props.settings.calendarMode === 'lunar' ? t('Декада', 'Decade') : t('Неделя', 'Week');
  const periodDates: string[] = [];
  for (let day = rangeStart; day <= rangeEnd && periodDates.length < 35; day = addCivilDays(day, 1)) periodDates.push(day);
  const [dayType, setDayType] = useState<'training' | 'rest'>('rest');
  const [editing, setEditing] = useState<string | null>(null); const [copyTo, setCopyTo] = useState(() => addCivilDays(todayCivilDate(props.context), 1));
  const [templateName, setTemplateName] = useState(''); const [deleteId, setDeleteId] = useState('');
  const summary = summaryForDay(props.store, date); const profile = profileFor(props)?.data; const target = profile && profile[dayType].energy > 0 ? profile[dayType] : undefined;
  const templates = physisRecords<DietTemplate>(props.store, 'diet-template');
  const dates = [...new Set(physisRecords<Meal>(props.store, 'meal').map(record => record.data.date))].sort().reverse();
  const editingRecord = summary.meals.find(record => record.id === editing);
  const displayedMeals = summary.meals.filter(record => !planning || record.data.status === 'planned');
  return <>
    <section className={`physis-panel${planning ? '' : ' physis-nutrition-today'}`}><header className={`physis-control-heading${planning ? '' : ' physis-nutrition-today-heading'}`}><div><h2>{planning ? t('Мой рацион', 'My nutrition plan') : t('Питание сегодня', 'Nutrition today')}</h2>{!planning && <p>{formatCalendarDateValue(date,props.settings.calendarMode,true,props.context)}</p>}</div>{planning ? <div className="shared-projects-switch physis-control-switch physis-equal-switch physis-plan-switch" role="group" aria-label={t('Период рациона', 'Nutrition plan period')}>{(['day', 'week', 'month'] as const).map((id,index) => <button type="button" key={id} aria-pressed={period === id} onClick={() => { setPeriod(id); setAnchor(date); }}>{[t('День','Day'),cycleLabel,t('Месяц','Month')][index]}</button>)}</div> : <button className="physis-primary" onClick={() => setEditing('new')}>{t('Добавить съеденное','Log food eaten')}</button>}</header>
      {planning ? <><div className="physis-plan-controls"><div className="physis-plan-field"><label htmlFor="physis-nutrition-day">{t('День рациона', 'Plan date')}</label><CalendarDatePicker id="physis-nutrition-day" value={date} mode={props.settings.calendarMode} calculationContext={props.context} onChange={value => { if (value) { setDate(value); setAnchor(value); setEditing(null); } }} ariaLabel={t('День рациона', 'Plan date')} /></div><div className="physis-plan-field"><label htmlFor="physis-nutrition-history">{t('История по дням', 'Diary history')}</label><select id="physis-nutrition-history" value={dates.includes(date) ? date : ''} onChange={event => { if (event.target.value) { setDate(event.target.value); setAnchor(event.target.value); setEditing(null); } }}><option value="">{t('Выберите записанный день', 'Choose a logged day')}</option>{dates.map(day => <option value={day} key={day}>{formatCalendarDateValue(day,props.settings.calendarMode,false,props.context)}</option>)}</select></div><button className="physis-primary" onClick={() => setWizardOpen(true)}>{t('Составить рацион','Build nutrition plan')}</button></div>
        {period !== 'day' && <><p>{formatCalendarDateValue(rangeStart,props.settings.calendarMode,false,props.context)} — {formatCalendarDateValue(rangeEnd,props.settings.calendarMode,false,props.context)}</p><div className="physis-nutrition-period-days">{periodDates.map(day => <button key={day} aria-current={day === date ? 'date' : undefined} onClick={() => { setDate(day); setEditing(null); }}>{formatCalendarDateValue(day,props.settings.calendarMode,false,props.context)}<small>{physisRecords<Meal>(props.store,'meal').filter(r => r.data.date === day && r.data.status === 'planned').length} {t('приёмов','meals')}</small></button>)}</div><button disabled={actions.busy || !displayedMeals.length} onClick={() => void actions.run(() => actions.submitCreation(`period:${date}:${rangeStart}:${rangeEnd}`,() => periodDates.filter(day => day !== date).flatMap(day => displayedMeals.filter(source => !physisRecords<Meal>(props.store,'meal').some(existing => existing.data.date === day && existing.data.copiedFrom === source.id)).map(source => newPhysisRecord('meal',copyMeal(source.data,day,source.id)))),props.store))}>{t('Повторить выбранный день на период', 'Repeat selected day across period')}</button><p className="physis-muted">{t('Добавляет плановые приёмы без замены записей. Съеденное отмечается отдельно в «Сегодня».', 'Adds planned meals while keeping existing records. Mark actual meals in Today.')}</p></>}
      </> : null}
    </section>
    {planning && <NutritionPlanWizard key={`${rangeStart}:${rangeEnd}`} props={props} dates={periodDates} open={wizardOpen} onClose={()=>setWizardOpen(false)} />}
    {editing && <NutritionMealDialog title={editingRecord ? t('Изменить приём пищи','Edit meal') : t('Новый приём пищи','New meal')} onClose={()=>setEditing(null)} language={props.language}><MealEditor key={editing} props={props} date={date} defaultStatus={planning ? "planned" : "actual"} record={editingRecord} onClose={()=>setEditing(null)} /></NutritionMealDialog>}
    <section className="physis-panel physis-diary-summary"><div className="physis-row"><h3>{planning ? t('План на выбранный день','Selected day plan') : t('Фактически съедено', 'Actually eaten')}</h3><label>{t('Сравнить с целью', 'Compare with target')}<select value={dayType} onChange={event => setDayType(event.target.value as 'training' | 'rest')}><option value="rest">{t('Восстановительный день', 'Rest day')}</option><option value="training">{t('Тренировочный день', 'Training day')}</option></select></label></div><NutrientSummary totals={planning ? summary.planned : summary.actual} target={target} props={props} />{!target && <p className="physis-muted">{t('Цели настраиваются в настройках Фюзиса. Учёт доступен без целей.', 'Set targets in Physis settings. Logging works without targets.')}</p>}<p className="physis-muted">{t('Неполный журнал не доказывает дефицит. «≥» — сумма известных значений, а не полный итог. БАДы и лекарства показаны отдельно в их разделе; инъекции в питание не включаются.', 'An incomplete diary does not establish deficiency. “≥” is the known subtotal. Supplements and medicines are shown separately; injections are excluded from nutrition.')}</p><details><summary>{t('План питания', 'Planned nutrition')}</summary><NutrientSummary totals={summary.planned} target={target} props={props} /><p>{t('План не становится фактом автоматически.', 'Planned meals never become actual meals automatically.')}</p></details></section>
    <section className="physis-panel physis-diary-meals"><h3>{t('Приёмы пищи', 'Meals')}</h3>{!displayedMeals.length && <p className="physis-empty">{t('На этот день приёмов пищи пока нет. Запишите завтрак, обед, ужин или перекус.', 'No meals for this day yet. Log breakfast, lunch, dinner or a snack.')}</p>}<div className="physis-nutrition-meals">{displayedMeals.toSorted((a, b) => a.data.time.localeCompare(b.data.time)).map(record => <article key={record.id}><div className="physis-row"><h4>{record.data.time} · {record.data.name}</h4><span className="physis-status">{record.data.status === 'actual' ? t('Съедено', 'Eaten') : t('План', 'Planned')}</span></div><ul>{record.data.items.map(item => <li key={item.id}>{item.food.name} · {fmt(item.quantity)} {item.unit === 'serving' ? t('порц.', 'servings') : item.unit}</li>)}</ul><NutrientSummary totals={totalNutrients(record.data.items)} props={props} compact />{record.data.note && <p>{record.data.note}</p>}<div className="physis-actions"><button onClick={() => setEditing(record.id)}>{t('Изменить', 'Edit')}</button>{record.data.status === 'planned' && <button disabled={actions.busy} onClick={() => void actions.run(() => props.store.save(editPhysisRecord(record, { ...record.data, status: 'actual' })))}>{t('Отметить съеденным', 'Mark eaten')}</button>}{planning && <button disabled={actions.busy} onClick={() => void actions.run(() => actions.submitCreation(`meal:${record.id}:${copyTo}`, () => [newPhysisRecord('meal', copyMeal(record.data, copyTo, record.id))], props.store))}>{t('Копировать на ', 'Copy to ')}{copyTo}</button>}<button onClick={() => setDeleteId(record.id)}>{t('Удалить', 'Delete')}</button></div>{deleteId === record.id && <div className="physis-warning"><p>{t('Удалить этот приём пищи из дневника?', 'Delete this meal from your diary?')}</p><div className="physis-actions"><button disabled={actions.busy} onClick={() => void actions.run(async () => { await props.store.remove(record.id); setDeleteId(''); })}>{t('Удалить приём', 'Delete meal')}</button><button onClick={() => setDeleteId('')}>{t('Отмена', 'Cancel')}</button></div></div>}</article>)}</div><ErrorMessage error={actions.error} /></section>
    {planning && summary.meals.some(record => record.data.status === 'actual') && <section className="physis-panel"><details><summary>{t('Съедено в выбранный день','Logged meals on selected day')}</summary><NutrientSummary totals={summary.actual} props={props} />{summary.meals.filter(record => record.data.status === 'actual').map(record => <div className="physis-row" key={record.id}><span>{record.data.time} · {record.data.name}</span><button onClick={() => setEditing(record.id)}>{t('Исправить запись','Correct entry')}</button></div>)}</details></section>}
    {planning && <section className="physis-panel physis-diary-reuse"><h3>{t('Повторить рацион', 'Reuse a day')}</h3><label>{t('Дата для копирования', 'Copy destination')}<CalendarDatePicker value={copyTo} mode={props.settings.inputCalendarMode} calculationContext={props.context} onChange={setCopyTo} ariaLabel={t('Дата копирования рациона', 'Copy diary to date')} /></label><div className="physis-actions"><button disabled={actions.busy || !summary.meals.length} onClick={() => void actions.run(() => actions.submitCreation(`day:${date}:${copyTo}`, () => summary.meals.map(record => newPhysisRecord('meal', copyMeal(record.data, copyTo, record.id))), props.store))}>{t('Копировать весь день в план', 'Copy whole day as a plan')}</button></div><p className="physis-muted">{t('Копии сохраняются как план с исходным составом; съеденное отмечается отдельно.', 'Copies retain composition snapshots and are saved as plans; eating is confirmed separately.')}</p><label>{t('Название шаблона рациона', 'Diet template name')}<input maxLength={200} value={templateName} onChange={event => setTemplateName(event.target.value)} /></label><button disabled={actions.busy || !summary.meals.length || !templateName.trim()} onClick={() => void actions.run(async () => { await actions.submitCreation(`template:${date}:${templateName.trim()}`, () => [newPhysisRecord('diet-template', { name: templateName.trim(), meals: summary.meals.map(record => copyMeal(record.data, date, record.id)) })], props.store); setTemplateName(''); })}>{t('Сохранить день как шаблон', 'Save day as a template')}</button>{templates.map(record => <div className="physis-row" key={record.id}><span>{record.data.name} · {record.data.meals.length} {t('приёмов', 'meals')}</span><button disabled={actions.busy} onClick={() => void actions.run(() => actions.submitCreation(`apply:${record.id}:${date}`, () => record.data.meals.map(meal => newPhysisRecord('meal', copyMeal(meal, date, record.id))), props.store))}>{t('Добавить в план ', 'Add to plan ')}{date}</button></div>)}</section>}
    <section className="physis-panel"><NutrientSources props={props} date={date} /></section>
  </>;
}

function MealEditor({ props, date, record, defaultStatus = 'actual', onClose }: { props: Props; date: string; record?: PhysisRecord<Meal>; defaultStatus?: Meal['status']; onClose: () => void }) {
  const t = tr(props.language); const actions = useActions();
  const [meal, setMeal] = useState<Meal>(() => structuredClone(record?.data ?? { date, time: '12:00', timeZone: props.settings.timeZone, name: t('Обед', 'Lunch'), status: defaultStatus, items: [], note: '' }));
  const [draftRecord] = useState(() => record ?? newPhysisRecord('meal', meal));
  return <section className="physis-panel"><h3>{record ? t('Изменить приём пищи', 'Edit meal') : t('Новый приём пищи', 'New meal')}</h3><form className="physis-form" onSubmit={event => { event.preventDefault(); void actions.run(async () => { await validateAndSave(props, editPhysisRecord(draftRecord, meal)); onClose(); }); }}><div className="physis-nutrition-fields"><label>{t('Приём пищи', 'Meal name')}<input required list="physis-meal-names" value={meal.name} maxLength={200} onChange={event => setMeal({ ...meal, name: event.target.value })} /><datalist id="physis-meal-names">{[t('Завтрак', 'Breakfast'), t('Обед', 'Lunch'), t('Полдник', 'Afternoon snack'), t('Ужин', 'Dinner'), t('Перекус', 'Snack')].map(name => <option key={name} value={name} />)}</datalist></label><label>{t('Время', 'Time')}<TimeClockPicker value={meal.time} ariaLabel={t('Время', 'Time')} onChange={time => setMeal({ ...meal, time })} /></label><label>{t('Статус', 'Status')}<select value={meal.status} onChange={event => setMeal({ ...meal, status: event.target.value as Meal['status'] })}><option value="actual">{t('Фактически съедено', 'Actually eaten')}</option><option value="planned">{t('Планирую съесть', 'Planned')}</option></select></label></div><IngredientPicker props={props} items={meal.items} onChange={items => setMeal({ ...meal, items })} />{meal.items.length > 0 && <NutrientSummary totals={totalNutrients(meal.items)} props={props} />}<label>{t('Заметка', 'Note')}<textarea value={meal.note} maxLength={10000} onChange={event => setMeal({ ...meal, note: event.target.value })} /></label><p className="physis-muted">{t('Сохраняется состав и порция на момент записи. Последующее изменение продукта не меняет этот приём пищи.', 'Food composition and portions are saved as a snapshot. Later catalog edits do not change this meal.')}</p><ErrorMessage error={actions.error} /><div className="physis-actions physis-nutrition-save"><button className="physis-primary" type="submit" disabled={actions.busy || meal.items.length === 0}>{actions.busy ? t('Сохраняется…', 'Saving…') : t('Сохранить приём пищи', 'Save meal')}</button><button type="button" disabled={actions.busy} onClick={onClose}>{t('Отмена', 'Cancel')}</button></div></form></section>;
}

function PortionPlanner({ props, totals, target, date, onAdd, empty=false }: { props: Props; totals: NutrientTotals; target?: NutritionTarget; date: string; empty?: boolean; onAdd?: (item: MealItem) => void }) {
  const t = tr(props.language); const actions = useActions(); const [selected, setSelected] = useState(''); const [key, setKey] = useState<NutrientKey>('protein');
  const catalog = catalogFor(props).filter(entry => !entry.food.archived); const food = catalog.find(entry => entry.id === selected);
  const goal = target && key in target ? target[key as keyof NutritionTarget] : null;
  const remaining = goal == null || !empty && totals[key].value === null ? null : Math.max(0, goal - totals[key].knownValue);
  const portion = food && remaining !== null ? suggestPortion(food.food, key, remaining) : null;
  const rules = profileFor(props)?.data.foodRules ?? DEFAULT_FOOD_RULES;
  const restricted = (entry: CatalogEntry) => rules.some(rule => rule.enabled && (entry.food.contains.includes(rule.category) || entry.food.mayContain.includes(rule.category)));
  const substitutes = food && remaining !== null ? catalog.filter(entry => entry.id !== food.id && !restricted(entry) && entry.food.compositionKnown).map(entry => ({ entry, portion: suggestPortion(entry.food, key, remaining) })).filter(entry => entry.portion).slice(0, 4) : [];
  return <section className="physis-panel"><h3>{t('Подобрать порцию к цели', 'Plan a portion toward your target')}</h3><p className="physis-muted">{t('Расчёт по одному выбранному показателю. Остальные БЖУ проверяются в дневнике; план остаётся редактируемым. Максимальная подсказка — 1000 г/мл.', 'Calculation for one chosen nutrient. Review other macros in the diary; the plan stays editable. Suggestions are capped at 1000 g/ml.')}</p><div className="physis-nutrition-fields"><label>{t('Показатель', 'Nutrient')}<select value={key} onChange={event => setKey(event.target.value as NutrientKey)}>{core.map(item => <option key={item} value={item}>{t(NUTRIENTS[item].ru, NUTRIENTS[item].en)}</option>)}</select></label><label>{t('Выбранный продукт', 'Chosen food')}<select value={selected} onChange={event => setSelected(event.target.value)}><option value="">{t('Выберите продукт', 'Select food')}</option>{catalog.map(entry => <option key={entry.id} value={entry.id}>{entry.food.name}</option>)}</select></label></div>{remaining === null ? <p>{t('Укажите цель и заполните состав продуктов: неизвестные значения не позволяют надёжно рассчитать остаток.', 'Set a target and complete food data; missing values prevent a reliable remaining amount.')}</p> : <p>{t('Остаток по журналу', 'Remaining from diary')}: {fmt(remaining)} {NUTRIENTS[key].unit}</p>}{food && <Warnings food={food.food} props={props} />}{portion && food && <><p>{food.food.name}: {fmt(portion.quantity)} {portion.unit}. {!portion.fulfills && t('В допустимую порцию цель не помещается.', 'The target cannot be reached within the portion limit.')}</p>{restricted(food) ? <p className="physis-warning">{t('Продукт попадает под ваше правило питания. Подберите замену или внесите его в план вручную; фактическую еду можно записать всегда.', 'This food matches a personal restriction. Choose a substitute or plan it manually; actual meals can always be logged.')}</p> : <button disabled={actions.busy} onClick={() => void actions.run(() => onAdd ? onAdd(snapshotItem(food.id,food.food,portion.quantity,portion.unit)) : actions.submitCreation(`portion:${date}:${food.id}:${key}`, () => [newPhysisRecord('meal', { date, time: '12:00', timeZone: props.settings.timeZone, name: t('Подобранная порция', 'Suggested portion'), status: 'planned', items: [snapshotItem(food.id, food.food, portion.quantity, portion.unit)], note: t('Расчёт по одному нутриенту; проверьте весь рацион.', 'Single-nutrient calculation; review the whole day.') })], props.store))}>{t('Добавить порцию в план', 'Add portion to plan')}</button>}{substitutes.length > 0 ? <><h4>{t('Возможные замены без выбранных ограничений', 'Substitutes without selected restrictions')}</h4>{substitutes.map(({ entry, portion: alternative }) => <div className="physis-row" key={entry.id}><span>{entry.food.name} · {fmt(alternative!.quantity)} {alternative!.unit} · {t('на 100', 'per 100')}: {fmt(entry.food.nutrients.energy?.value)} kcal; {t('Б/Ж/У', 'P/F/C')} {fmt(entry.food.nutrients.protein?.value)}/{fmt(entry.food.nutrients.fat?.value)}/{fmt(entry.food.nutrients.carbohydrate?.value)} g</span><button onClick={() => setSelected(entry.id)}>{t('Выбрать', 'Choose')}</button></div>)}</> : <p>{t('Подходящих замен с известным составом нет.', 'No suitable substitutes with known composition.')}</p>}</>}<ErrorMessage error={actions.error} /></section>;
}


type TargetDraft = Record<'energy' | 'protein' | 'fat' | 'carbohydrate' | 'fiber', string>;
function targetDraft(target: NutritionTarget, profile: NutritionProfile): TargetDraft {
  const divisor = (key: 'protein' | 'fat' | 'carbohydrate') => profile.macroUnit === 'energy-percent' ? target.energy / (key === 'fat' ? 9 : 4) / 100 : profile.macroUnit === 'g-per-kg' ? profile.weightKg ?? 1 : 1;
  return { energy: String(target.energy || ''), protein: target.protein ? String(Number((target.protein / divisor('protein')).toFixed(3))) : '', fat: target.fat ? String(Number((target.fat / divisor('fat')).toFixed(3))) : '', carbohydrate: target.carbohydrate ? String(Number((target.carbohydrate / divisor('carbohydrate')).toFixed(3))) : '', fiber: String(target.fiber ?? '') };
}
export type NutritionSettingsHandle = { resolve: () => NutritionProfile };
export function NutritionSettings(props: Props & { calculatorOnly?: boolean; personalDraft?: PersonalProfileDraft; editorRef?: Ref<NutritionSettingsHandle> }) {
  const Form = props.personalDraft ? 'div' : 'form';
  const t = tr(props.language); const actions = useActions(); const record = profileFor(props);
  const [profile, setProfile] = useState<NutritionProfile>(() => structuredClone(record?.data ?? defaultNutritionProfile()));
  const [draftRecord] = useState(() => record ?? newPhysisRecord('nutrition-profile', profile));
  const [anthropometrics, setAnthropometrics] = useState({ age: String(profile.age ?? ''), heightCm: String(profile.heightCm ?? ''), weightKg: String(profile.weightKg ?? ''), activityFactor: String(profile.activityFactor) });
  const [drafts, setDrafts] = useState({ training: targetDraft(profile.training, profile), rest: targetDraft(profile.rest, profile) });
  const [estimate, setEstimate] = useState(''); const [message, setMessage] = useState('');
  function parameters() {
    if (props.personalDraft) {
      let next: NutritionProfile;
      try { next = applyPersonalProfile(profile, props.personalDraft); }
      catch { throw new Error(t('Проверьте пол, возраст, рост и вес.', 'Check sex, age, height and weight.')); }
      return { age: next.age, heightCm: next.heightCm, weightKg: next.weightKg, formulaSex: next.formulaSex, activityFactor: next.activityFactor, activitySource: next.activitySource, goal: next.goal, personal: next.personal, method: next.method };
    }
    const age = anthropometrics.age.trim() ? physisNumber(anthropometrics.age, 0, 120) : null;
    const heightCm = anthropometrics.heightCm.trim() ? physisNumber(anthropometrics.heightCm, 1, 250) : null;
    const weightKg = anthropometrics.weightKg.trim() ? physisNumber(anthropometrics.weightKg, 1, 400) : null;
    const activityFactor = physisNumber(anthropometrics.activityFactor, 1, 2.5);
    if (activityFactor === null || (anthropometrics.age.trim() && age === null) || (anthropometrics.heightCm.trim() && heightCm === null) || (anthropometrics.weightKg.trim() && weightKg === null)) throw new Error(t('Проверьте параметры профиля.', 'Check profile parameters.'));
    return { age, heightCm, weightKg, activityFactor };
  }
  function resolve(day: 'training' | 'rest') {
    if (Object.values(drafts[day]).every(value => !value.trim())) return { energy: 0, protein: 0, fat: 0, carbohydrate: 0, fiber: null };
    const draft = drafts[day]; const inputs = Object.fromEntries(Object.entries(draft).map(([key, value]) => [key, value.trim() ? physisNumber(value, 0, 50000) : key === 'fiber' ? null : key === 'energy' && profile.mode === 'macros' && profile.macroUnit !== 'energy-percent' ? 0 : null])) as Record<keyof TargetDraft, number | null>;
    if (['protein', 'fat', 'carbohydrate'].some(key => inputs[key as keyof TargetDraft] === null) || inputs.energy === null || (draft.fiber.trim() && inputs.fiber === null)) throw new Error(t('Заполните БЖУ и калорийность, где она требуется.', 'Complete macros and calories where required.'));
    return resolveTargets({ ...inputs, energy: inputs.energy, protein: inputs.protein!, fat: inputs.fat!, carbohydrate: inputs.carbohydrate!, mode: profile.mode, unit: profile.macroUnit, weightKg: parameters().weightKg });
  }
  function buildProfile() {
    const next = { ...profile, ...parameters(), training: resolve('training'), rest: resolve('rest') };
    if (next.method === 'mifflin-st-jeor') estimateEnergy(next);
    return next;
  }
  useImperativeHandle(props.editorRef, () => ({ resolve: buildProfile }));
  return <section className="physis-panel"><h2>{props.calculatorOnly ? t('Расчёт калорий и БЖУ','Calorie and macro calculator') : t('Питание: профиль, цели и правила', 'Nutrition profile, targets and rules')}</h2><Form className="physis-form physis-nutrition-settings-form" onSubmit={props.personalDraft ? undefined : event => { event.preventDefault(); void actions.run(async () => { const next = buildProfile(); await validateAndSave(props, editPhysisRecord(draftRecord, next)); setMessage(t('Цели и правила сохранены.', 'Targets and rules saved.')); }); }}><div className="physis-nutrition-fields"><label>{t('Режим', 'Mode')}<select value={profile.mode} onChange={event => setProfile({ ...profile, mode: event.target.value as NutritionProfile['mode'] })}><option value="macros">{t('По БЖУ — рекомендуемый интерфейс Фюзиса', 'By macros — Physis recommended interface')}</option><option value="calories">{t('По калорийности', 'By calories')}</option></select></label><label>{t('Единица целей БЖУ', 'Macro target unit')}<select value={profile.macroUnit} onChange={event => { setProfile({ ...profile, macroUnit: event.target.value as NutritionProfile['macroUnit'] }); setDrafts({ training: { energy: drafts.training.energy, protein: '', fat: '', carbohydrate: '', fiber: drafts.training.fiber }, rest: { energy: drafts.rest.energy, protein: '', fat: '', carbohydrate: '', fiber: drafts.rest.fiber } }); }}><option value="g">{t('Граммы в сутки', 'Grams per day')}</option><option value="energy-percent">{t('Проценты энергии (сумма 100%)', 'Energy percentages (total 100%)')}</option><option value="g-per-kg">{t('Граммы на кг массы тела', 'Grams per kg body mass')}</option></select></label>{!props.personalDraft && <label>{t('Цель', 'Goal')}<select value={profile.goal} onChange={event => setProfile({ ...profile, goal: event.target.value as NutritionProfile['goal'] })}>{(['maintain', 'lose', 'gain', 'custom'] as const).map((goal, index) => <option value={goal} key={goal}>{t(['Поддержание', 'Снижение массы', 'Набор', 'Своя цель'][index], ['Maintain', 'Lose weight', 'Gain weight', 'Custom'][index])}</option>)}</select></label>}</div><p className="physis-muted">{t('БЖУ — выбор интерфейса, а не медицинское превосходство. Цели задаются вручную; выбор снижения массы сам по себе не назначает дефицит калорий.', 'Macros are an interface preference, not a medical superiority claim. Targets are manual; selecting weight loss does not prescribe a calorie deficit.')}</p><details><summary>{t('Параметры и стартовая оценка для взрослых', 'Optional adult starting estimate')}</summary>{!props.personalDraft && <div className="physis-nutrition-fields">{(['age', 'heightCm', 'weightKg', 'activityFactor'] as const).map((key, index) => <label key={key}>{t(['Возраст, лет', 'Рост, см', 'Масса, кг', 'Коэффициент активности (1–2,5)'][index], ['Age, years', 'Height, cm', 'Body mass, kg', 'Activity factor (1–2.5)'][index])}<input inputMode="decimal" value={anthropometrics[key]} onChange={event => setAnthropometrics({ ...anthropometrics, [key]: event.target.value })} /></label>)}<label>{t('Параметр формулы', 'Formula parameter')}<select value={profile.formulaSex} onChange={event => setProfile({ ...profile, formulaSex: event.target.value as NutritionProfile['formulaSex'] })}><option value="female">{t('Женский (−161)', 'Female (−161)')}</option><option value="male">{t('Мужской (+5)', 'Male (+5)')}</option></select></label></div>}<label className="physis-nutrition-check"><input type="checkbox" checked={profile.excluded} onChange={event => setProfile({ ...profile, excluded: event.target.checked, method: event.target.checked ? 'manual' : profile.method })} />{t('Беременность, лактация или другая ситуация вне области взрослой формулы', 'Pregnancy, lactation or another situation outside the adult formula')}</label><button type="button" onClick={() => void actions.run(() => { const result = estimateEnergy({ ...profile, ...parameters() }); setEstimate(`${t('Расчётный обмен в покое', 'Estimated resting energy')}: ${fmt(result.resting)} kcal; ${t('поддержание', 'maintenance')}: ${fmt(result.maintenance)} kcal. ${result.version}`); setProfile({ ...profile, method: 'mifflin-st-jeor', formulaVersion: result.version, formulaSource: result.source }); })}>{t('Рассчитать стартовую оценку', 'Calculate starting estimate')}</button>{estimate && <p role="status">{estimate}</p>}<p className="physis-muted">{t('Mifflin–St Jeor, 1990. Это оценка, не измерение обмена. Активность уже включена коэффициентом; калории часов и тренировок автоматически не прибавляются. Для несовершеннолетних и исключённых ситуаций доступен ручной учёт.', 'Mifflin–St Jeor, 1990. This is an estimate, not a measurement. The factor already includes activity; watch and workout calories are never added automatically. Manual tracking remains available outside scope.')} <a href="https://doi.org/10.1093/ajcn/51.2.241" target="_blank" rel="noreferrer">{t('Источник формулы', 'Formula source')}</a></p>{!props.personalDraft && <label>{t('Основание коэффициента активности', 'Activity factor source')}<input value={profile.activitySource} onChange={event => setProfile({ ...profile, activitySource: event.target.value })} maxLength={500} /></label>}<button type="button" onClick={() => setProfile({ ...profile, method: 'manual', formulaSource: t('Пользователь', 'User'), formulaVersion: 'manual v1' })}>{t('Использовать только ручные цели', 'Use manual targets only')}</button></details>
    {(['rest', 'training'] as const).map(day => <fieldset key={day}><legend>{day === 'rest' ? t('Восстановительный день', 'Rest day') : t('Тренировочный день', 'Training day')}</legend><div className="physis-nutrition-fields">{(Object.keys(drafts[day]) as (keyof TargetDraft)[]).map(key => <label key={key}>{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)} ({key === 'energy' ? 'kcal' : key === 'fiber' ? 'g' : profile.macroUnit === 'g' ? 'g' : profile.macroUnit === 'energy-percent' ? '%' : 'g/kg'})<input inputMode="decimal" value={drafts[day][key]} onChange={event => { setMessage(''); setDrafts({ ...drafts, [day]: { ...drafts[day], [key]: event.target.value } }); }} disabled={key === 'energy' && profile.mode === 'macros' && profile.macroUnit !== 'energy-percent'} placeholder={key === 'energy' && profile.mode === 'macros' && profile.macroUnit !== 'energy-percent' ? t('Из БЖУ', 'From macros') : ''} /></label>)}</div><button type="button" onClick={() => void actions.run(() => { const result = resolve(day); setEstimate(`${day === 'rest' ? t('Восстановление', 'Rest') : t('Тренировка', 'Training')}: ${fmt(result.energy)} kcal; ${t('Б/Ж/У', 'P/F/C')}: ${fmt(result.protein)}/${fmt(result.fat)}/${fmt(result.carbohydrate)} g`); })}>{t('Проверить расчёт', 'Check calculation')}</button></fieldset>)}{estimate && <p className="physis-status" role="status">{estimate}</p>}{!props.calculatorOnly && <><fieldset><legend>{t('Показатели дневной сводки', 'Daily summary nutrients')}</legend><div className="physis-nutrition-fields">{NUTRIENT_KEYS.filter(key => !core.includes(key)).map(key => <label key={key} className="physis-nutrition-check"><input type="checkbox" checked={profile.selectedNutrients.includes(key)} onChange={event => setProfile({ ...profile, selectedNutrients: event.target.checked ? [...profile.selectedNutrients, key] : profile.selectedNutrients.filter(item => item !== key) })} />{t(NUTRIENTS[key].ru, NUTRIENTS[key].en)}</label>)}</div></fieldset><fieldset><legend>{t('Личные правила питания', 'Personal food rules')}</legend>{profile.foodRules.map((rule, index) => <div key={rule.id}><label className="physis-nutrition-check"><input type="checkbox" checked={rule.enabled} onChange={event => setProfile({ ...profile, foodRules: profile.foodRules.map((item, position) => position === index ? { ...item, enabled: event.target.checked, reviewedAt: todayCivilDate(props.context) } : item) })} />{t(...categoryNames[rule.category])}</label><label>{t('Текст правила', 'Rule text')}<input value={rule.text} onChange={event => setProfile({ ...profile, foodRules: profile.foodRules.map((item, position) => position === index ? { ...item, text: event.target.value, reviewedAt: todayCivilDate(props.context) } : item) })} /></label></div>)}<p className="physis-muted">{t('Это личные ограничения. Предупреждения не блокируют запись съеденного; они не объявляют все бобовые, сою или масла вредными.', 'These are personal preferences. Warnings never block actual meal logging and do not label all legumes, soy or oils harmful.')}</p></fieldset></>}<ErrorMessage error={actions.error} />{message && <p role="status">{message}</p>}{!props.personalDraft && <button className="physis-primary" disabled={actions.busy} type="submit">{props.calculatorOnly ? t('Сохранить цели','Save targets') : t('Сохранить цели и правила', 'Save targets and rules')}</button>}</Form></section>;
}
